(function(){
  const esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
  const clean=v=>String(v??"").replace(/[<>]/g,"").trim();
  const now=()=>new Date().toISOString();
  const clock=v=>new Date(v||Date.now()).toLocaleTimeString("ar-SA",{hour:"2-digit",minute:"2-digit"});
  const stage=p=>p>=100?"مكتمل":p>=82?"المراجعة":p>=60?"إعداد التقرير":p>=35?"التحليل":"جمع البيانات";
  state.rules=state.rules||[
    {id:"spend",scope:"الشركة",text:"ممنوع أي إنفاق دون موافقة نواف الصريحة",level:"FINANCIAL",locked:true},
    {id:"mueen-content",scope:"مُعِين",text:"تغييرات المحتوى الديني تتطلب مراجعة الرئيس التنفيذي",level:"APPROVAL_REQUIRED",locked:true}
  ];
  state.requests=state.requests||[];
  state.activities=state.activities.map((a,i)=>Object.assign({id:"legacy-"+i,createdAt:now()},a));
  state.tasks.forEach(t=>{t.status=t.status||(t.progress>=100?"COMPLETED":"ACTIVE");t.history=t.history||[{at:now(),text:"تمت مزامنة المهمة مع حالة الشركة"}];});
  state.reports.forEach(r=>{r.createdAt=r.createdAt||now();r.updatedAt=r.updatedAt||r.createdAt;r.completedAt=r.progress>=100?(r.completedAt||r.updatedAt):null;r.department=r.department||(emp(r.author)?.department||"");r.status=r.status||r.stage;r.history=r.history||[{at:r.createdAt,stage:r.stage,progress:r.progress}];});
  state.decisions.forEach(d=>{d.expectedBenefit=d.expectedBenefit||"تحريك العمل ورفع أثر المشروع";d.relatedTask=d.relatedTask||"t1";d.status=d.status||"WAITING_APPROVAL";d.createdAt=d.createdAt||now();});
  state.projects.forEach(p=>{p.manager=p.manager||p.team[0];p.health=p.health||p.progress;p.departmentRequests=p.departmentRequests||[];});
  state.employees.forEach(e=>{e.permissions=e.permissions||"AUTO_INTERNAL";e.responsibilities=e.responsibilities||e.instructions||"تنفيذ المهام المتخصصة ورفع النتائج";e.projectIds=e.projectIds||[e.project==="مُعِين"?"m":"q"];e.completedTaskIds=e.completedTaskIds||state.tasks.filter(t=>t.employee===e.id&&t.progress===100).map(t=>t.id);e.history=e.history||state.activities.filter(a=>a.text.includes(e.name)).map(a=>({at:a.createdAt,text:a.text}));});
  save();

  function event(text,kind,links){const a={id:"ev-"+Date.now()+Math.random().toString(16).slice(2),text,kind:kind||"SIM",createdAt:now(),links:links||{}};state.activities.unshift(a);if(a.links.employee){const e=emp(a.links.employee);if(e){e.history=e.history||[];e.history.unshift({at:a.createdAt,text:a.text});}}return a;}
  function closeButton(){return '<button class="dialog-close" data-close>إغلاق</button>';}
  function open(html,wide=true){modal('<div class="'+(wide?'dialog-wide':'')+'">'+html+'</div>');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$("#modal").classList.remove("open"));}
  function departments(){return ["إدارة المشاريع","التقنية والتطوير","التصميم","التسويق","البحث والابتكار","الأعمال والمالية","التحليلات"];}
  function addEmployeeView(){open('<div class="workspace-head"><div><h2>إضافة موظف AI</h2><p class="muted">سجل مركزي يظهر مباشرة في المكتب والمشاريع والتحليلات</p></div>'+closeButton()+'</div><form id="add-employee-form" class="form-grid"><label>الاسم<input name="name" required></label><label>الدور<input name="role" required></label><label>القسم<select name="department">'+departments().map(d=>'<option>'+d+'</option>').join('')+'</select></label><label>المشروع<select name="project">'+state.projects.map(p=>'<option>'+esc(p.name)+'</option>').join('')+'</select></label><label>المهمة الحالية<input name="task" value="بانتظار التكليف"></label><label>الحالة<select name="status"><option>IDLE</option><option>WORKING</option><option>RESEARCHING</option><option>COLLABORATING</option><option>REVIEWING</option><option>WAITING_APPROVAL</option></select></label><label>الصلاحيات<select name="permissions"><option>AUTO_INTERNAL</option><option>APPROVAL_REQUIRED</option></select></label><label class="form-wide">المسؤوليات<textarea name="responsibilities"></textarea></label><label class="form-wide">تعليمات الوكيل<textarea name="instructions"></textarea></label><button class="primary form-wide">إنشاء الموظف وربطه بالشركة</button></form>');$("#add-employee-form").onsubmit=x=>{x.preventDefault();const data=Object.fromEntries([...new FormData(x.target)].map(([k,v])=>[k,clean(v)])),id='emp-'+Date.now();state.employees.push({...data,id,progress:0,productivity:70,projectIds:[data.project==='مُعِين'?'m':'q'],completedTaskIds:[],history:[{at:now(),text:'انضم إلى القوة العاملة في Nawaf HQ'}]});event('تمت إضافة '+data.name+' إلى قسم '+data.department,'REAL',{employee:id});save();render();toast('تمت إضافة الموظف وربطه بالشركة');};}
  function requestView(e){open('<div class="workspace-head"><div><h2>طلب تعاون جديد</h2><p class="muted">من '+esc(e.name)+' · '+esc(e.department)+'</p></div>'+closeButton()+'</div><form id="request-form"><label>القسم المستلم</label><select name="to">'+departments().filter(d=>d!==e.department).map(d=>'<option>'+d+'</option>').join('')+'</select><label>عنوان الطلب</label><input name="title" required placeholder="ما المطلوب؟"><label>التفاصيل</label><textarea name="details" required></textarea><button class="primary">إرسال الطلب وربطه بسير العمل</button></form>');$("#request-form").onsubmit=x=>{x.preventDefault();const data=Object.fromEntries([...new FormData(x.target)].map(([k,v])=>[k,clean(v)])),r={...data,id:'req-'+Date.now(),from:e.department,requester:e.id,status:'جديد',createdAt:now()};state.requests.unshift(r);e.status='COLLABORATING';event(e.name+' أرسل طلب تعاون إلى قسم '+data.to,'SIM',{employee:e.id,project:e.projectIds[0]});save();render();toast('وصل الطلب إلى '+data.to);};}
  function taskView(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;const e=emp(t.employee),p=pr(t.project),r=state.reports.find(x=>x.task===id||x.author===t.employee&&x.project===t.project);open('<div class="workspace-head"><div><h2>'+esc(t.title)+'</h2><p class="muted">'+esc(p.name)+' · '+esc(e.name)+' · '+esc(e.department)+'</p></div><div class="workspace-badges"><span class="badge real">حالة مرتبطة</span><span class="badge">'+esc(t.status)+'</span>'+closeButton()+'</div></div><div class="detail-grid"><div class="detail-box"><b>'+t.progress+'%</b><small>التقدم</small></div><div class="detail-box"><b>'+esc(e.status)+'</b><small>حالة الموظف</small></div><div class="detail-box"><b>'+esc(r?r.stage:"لا يوجد")+'</b><small>المخرج</small></div></div><div class="bar"><i style="width:'+t.progress+'%"></i></div><h3>خط المهمة</h3><div class="timeline">'+(t.history||[]).map(h=>'<div class="timeline-item"><time>'+clock(h.at)+'</time><i></i><span>'+esc(h.text)+'</span></div>').join('')+'</div>');}

  const originalEmployee=window.employee;
  window.employee=function(id){if(!id)return addEmployeeView();const e=emp(id);if(!e)return;const tasks=state.tasks.filter(t=>t.employee===id),reports=state.reports.filter(r=>r.author===id),history=e.history||[],sent=state.requests.filter(r=>r.from===e.department),received=state.requests.filter(r=>r.to===e.department);open('<div class="workspace-head"><div><h2>مساحة '+esc(e.name)+'</h2><p class="muted">'+esc(e.role)+' · '+esc(e.department)+'</p></div><div class="workspace-badges"><span class="badge '+(e.status==="WAITING_APPROVAL"?'wait':'real')+'">'+esc(status(e.status))+'</span><span class="badge">'+esc(e.permissions)+'</span>'+closeButton()+'</div></div><div class="detail-grid"><div class="detail-box"><b>'+esc(e.productivity)+'%</b><small>الإنتاجية</small></div><div class="detail-box"><b>'+tasks.filter(t=>t.progress===100).length+'</b><small>مهام مكتملة</small></div><div class="detail-box"><b>'+reports.length+'</b><small>تقارير محفوظة</small></div><div class="detail-box"><b>'+tasks.filter(t=>t.progress<100).length+'</b><small>عبء حالي</small></div><div class="detail-box"><b>'+sent.length+'</b><small>طلبات مرسلة</small></div><div class="detail-box"><b>'+received.length+'</b><small>طلبات مستلمة</small></div></div><div class="split"><section><h3>العمل الحالي</h3>'+tasks.map(t=>'<div class="report click-task" data-task="'+esc(t.id)+'"><b>'+esc(t.title)+'</b><small>'+t.progress+'% · '+esc(t.status)+'</small><div class="bar"><i style="width:'+t.progress+'%"></i></div></div>').join('')+'<button class="secondary-action" id="new-request">إرسال طلب لقسم آخر</button><h3>سجل العمل</h3><div class="timeline">'+history.map(h=>'<div class="timeline-item"><time>'+clock(h.at)+'</time><i></i><span>'+esc(h.text)+'</span></div>').join('')+'</div></section><section><h3>إدارة الموظف</h3><form id="edit-employee"><label>الاسم</label><input name="name" value="'+esc(e.name)+'" required><label>الدور</label><input name="role" value="'+esc(e.role)+'"><label>القسم</label><select name="department">'+departments().map(d=>'<option '+(d===e.department?'selected':'')+'>'+esc(d)+'</option>').join('')+'</select><label>المشروع</label><select name="project">'+state.projects.map(p=>'<option '+(p.name===e.project?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select><label>المهمة الحالية</label><input name="task" value="'+esc(e.task)+'"><label>الحالة</label><select name="status">'+["WORKING","RESEARCHING","COLLABORATING","IDLE","REVIEWING","WAITING_APPROVAL","COMPLETED"].map(s=>'<option '+(s===e.status?'selected':'')+'>'+s+'</option>').join('')+'</select><label>الإنتاجية</label><input name="productivity" type="number" min="0" max="100" value="'+esc(e.productivity)+'"><label>الصلاحيات</label><select name="permissions"><option '+(e.permissions==='AUTO_INTERNAL'?'selected':'')+'>AUTO_INTERNAL</option><option '+(e.permissions==='APPROVAL_REQUIRED'?'selected':'')+'>APPROVAL_REQUIRED</option></select><label>المسؤوليات</label><textarea name="responsibilities">'+esc(e.responsibilities)+'</textarea><label>تعليمات الوكيل</label><textarea name="instructions">'+esc(e.instructions)+'</textarea><button class="primary">حفظ السجل الموحد</button></form></section></div>');document.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>taskView(x.dataset.task));$("#new-request").onclick=()=>requestView(e);$("#edit-employee").onsubmit=x=>{x.preventDefault();const data=Object.fromEntries([...new FormData(x.target)].map(([k,v])=>[k,clean(v)]));data.productivity=Math.max(0,Math.min(100,Number(data.productivity)||0));Object.assign(e,data,{projectIds:[data.project==='مُعِين'?'m':'q']});event('تم تحديث سجل '+e.name,'REAL',{employee:e.id});save();render();toast('تم تحديث الموظف في جميع المساحات');};};

  window.project=function(id){const p=pr(id),tasks=state.tasks.filter(t=>t.project===id),reports=state.reports.filter(r=>r.project===id),decs=state.decisions.filter(d=>d.project===p.name),requests=state.requests.filter(r=>tasks.some(t=>t.id===r.task)||r.project===id),acts=state.activities.filter(a=>a.links&&a.links.project===id||a.text.includes(p.name)).slice(0,8),manager=emp(p.manager);open('<div class="workspace-head"><div><h2>مشروع '+esc(p.name)+'</h2><p class="muted">'+esc(p.phase)+' · المدير '+esc(manager?.name||'غير محدد')+'</p></div><div class="workspace-badges"><span class="badge real">صحة '+p.progress+'%</span>'+closeButton()+'</div></div><div class="detail-grid"><div class="detail-box"><b>'+p.progress+'%</b><small>التقدم</small></div><div class="detail-box"><b>'+tasks.filter(t=>t.progress<100).length+'</b><small>مهام نشطة</small></div><div class="detail-box"><b>'+decs.length+'</b><small>قرارات معلقة</small></div><div class="detail-box"><b>'+p.team.length+'</b><small>أعضاء الفريق</small></div><div class="detail-box"><b>'+reports.length+'</b><small>تقارير</small></div><div class="detail-box"><b>'+requests.length+'</b><small>طلبات أقسام</small></div></div><div class="workspace-badges">'+p.team.map(x=>'<button class="badge" data-open-emp="'+x+'">'+esc(emp(x)?.name||x)+'</button>').join('')+'</div><div class="split"><section><h3>المهام</h3>'+tasks.map(t=>'<div class="report click-task" data-task="'+t.id+'"><b>'+esc(t.title)+'</b><small>'+esc(emp(t.employee).name)+' · '+t.progress+'%</small><div class="bar"><i style="width:'+t.progress+'%"></i></div></div>').join('')+'</section><section><h3>التقارير</h3>'+reports.map(r=>'<div class="report click-task" data-open-report="'+r.id+'"><b>'+esc(r.title)+'</b><small>'+esc(r.stage)+' · '+r.progress+'%</small></div>').join('')+'<h3>العوائق</h3><p>'+esc(p.issues.join('، ')||'لا توجد عوائق')+'</p><h3>طلبات الأقسام</h3><p>'+esc(requests.map(r=>r.title).join('، ')||'لا توجد طلبات')+'</p></section></div><h3>آخر التغييرات</h3><div class="timeline">'+acts.map(a=>'<div class="timeline-item"><time>'+clock(a.createdAt)+'</time><i></i><span>'+esc(a.text)+'</span></div>').join('')+'</div>');document.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>taskView(x.dataset.task));document.querySelectorAll('[data-open-report]').forEach(x=>x.onclick=()=>report(x.dataset.openReport));document.querySelectorAll('[data-open-emp]').forEach(x=>x.onclick=()=>employee(x.dataset.openEmp));};

  window.department=function(name){const es=state.employees.filter(e=>e.department===name),tasks=state.tasks.filter(t=>es.some(e=>e.id===t.employee)),incoming=state.requests.filter(r=>r.to===name),outgoing=state.requests.filter(r=>r.from===name),reports=state.reports.filter(r=>es.some(e=>e.id===r.author)),performance=tasks.length?Math.round(tasks.reduce((n,t)=>n+t.progress,0)/tasks.length):0;open('<div class="workspace-head"><div><h2>قسم '+esc(name)+'</h2><p class="muted">مساحة عمل مترابطة مع المشاريع والطلبات والمخرجات</p></div>'+closeButton()+'</div><div class="detail-grid"><div class="detail-box"><b>'+es.length+'</b><small>فريق القسم</small></div><div class="detail-box"><b>'+tasks.filter(t=>t.progress<100).length+'</b><small>عبء نشط</small></div><div class="detail-box"><b>'+incoming.length+'</b><small>طلبات واردة</small></div><div class="detail-box"><b>'+performance+'%</b><small>أداء القسم</small></div><div class="detail-box"><b>'+reports.length+'</b><small>مخرجات محفوظة</small></div><div class="detail-box"><b>'+outgoing.length+'</b><small>تعاون صادر</small></div></div><div class="split"><section><h3>الموظفون</h3>'+es.map(e=>'<div class="report click-task" data-open-emp="'+e.id+'"><b>'+esc(e.name)+'</b><small>'+esc(e.task)+' · '+esc(status(e.status))+'</small></div>').join('')+'</section><section><h3>طلبات التعاون</h3>'+(incoming.length?incoming.map(r=>'<div class="report"><b>'+esc(r.title)+'</b><small>'+esc(r.from)+' · '+esc(r.status)+'</small></div>').join(''):'<div class="empty-state">لا توجد طلبات جديدة</div>')+'<h3>المخرجات</h3>'+reports.map(r=>'<div class="report click-task" data-open-report="'+r.id+'"><b>'+esc(r.title)+'</b><small>'+esc(r.stage)+'</small></div>').join('')+'</section></div>');document.querySelectorAll('[data-open-emp]').forEach(x=>x.onclick=()=>employee(x.dataset.openEmp));document.querySelectorAll('[data-open-report]').forEach(x=>x.onclick=()=>report(x.dataset.openReport));};

  window.report=function(id){const r=state.reports.find(x=>x.id===id),e=emp(r.author),p=pr(r.project);open('<div class="workspace-head"><div><h2>'+esc(r.title)+'</h2><p class="muted">'+esc(e.name)+' · '+esc(p.name)+'</p></div><div class="workspace-badges"><span class="badge">'+esc(r.stage)+'</span>'+closeButton()+'</div></div><div class="detail-grid"><div class="detail-box"><b>'+r.progress+'%</b><small>التقدم</small></div><div class="detail-box"><b>'+esc(r.department)+'</b><small>القسم</small></div><div class="detail-box"><b>'+clock(r.createdAt)+'</b><small>وقت الإنشاء</small></div><div class="detail-box"><b>'+esc(r.task||'—')+'</b><small>المهمة المرتبطة</small></div><div class="detail-box"><b>'+esc(r.status)+'</b><small>الحالة</small></div><div class="detail-box"><b>'+(r.completedAt?clock(r.completedAt):'قيد العمل')+'</b><small>وقت الإكمال</small></div></div><div class="bar"><i style="width:'+r.progress+'%"></i></div><h3>المحتوى المحفوظ</h3><div class="report"><p>'+esc(r.content)+'</p></div><h3>دورة التقرير</h3><div class="timeline">'+(r.history||[]).map(h=>'<div class="timeline-item"><time>'+clock(h.at)+'</time><i></i><span>'+esc(h.stage)+' — '+h.progress+'%</span></div>').join('')+'</div><p class="muted">🔵 مخرج داخلي. لا يمثل إجراءً خارجيًا ما لم يُعلّم كإجراء متصل.</p>');};

  window.rules=function(){open('<div class="workspace-head"><div><h2>دستور الشركة</h2><p class="muted">قواعد تنفيذية تتحقق منها تدفقات العمل</p></div>'+closeButton()+'</div><form id="rules-form">'+state.rules.map(r=>'<div class="rule-row"><input name="text-'+r.id+'" value="'+esc(r.text)+'" '+(r.locked?'readonly':'')+'><select name="level-'+r.id+'" '+(r.locked?'disabled':'')+'><option '+(r.level==='AUTO'?'selected':'')+'>AUTO</option><option '+(r.level==='APPROVAL_REQUIRED'?'selected':'')+'>APPROVAL_REQUIRED</option><option '+(r.level==='FINANCIAL'?'selected':'')+'>FINANCIAL</option></select><span class="badge '+(r.locked?'wait':'')+'">'+esc(r.scope)+(r.locked?' · ثابت':'')+'</span></div>').join('')+'<div class="detail-actions"><button type="button" id="add-rule">إضافة قاعدة</button><button class="primary">حفظ الدستور</button></div></form>');$("#add-rule").onclick=()=>{state.rules.push({id:'rule-'+Date.now(),scope:'الشركة',text:'قاعدة جديدة',level:'APPROVAL_REQUIRED',locked:false});save();rules();};$("#rules-form").onsubmit=x=>{x.preventDefault();const f=new FormData(x.target);state.rules.forEach(r=>{if(!r.locked){r.text=f.get('text-'+r.id);r.level=f.get('level-'+r.id);}});event('تم تحديث دستور الشركة','REAL');save();render();toast('تم حفظ القواعد التنفيذية');};};

  window.analytics=function(){const active=state.tasks.filter(t=>t.progress<100).length,done=state.tasks.length-active,reportCount=state.reports.length,approvalAge=state.decisions.length?Math.round(state.decisions.length*6):0;open('<div class="workspace-head"><div><h2>تحليلات الشركة</h2><p class="muted">محسوبة لحظيًا من الحالة المشتركة</p></div>'+closeButton()+'</div><div class="detail-grid"><div class="detail-box"><b>'+avg()+'%</b><small>إنتاجية الفريق</small></div><div class="detail-box"><b>'+active+'</b><small>مهام نشطة</small></div><div class="detail-box"><b>'+done+'</b><small>مهام مكتملة</small></div><div class="detail-box"><b>'+reportCount+'</b><small>تقارير منتجة</small></div><div class="detail-box"><b>'+state.requests.length+'</b><small>تعاون بين الأقسام</small></div><div class="detail-box"><b>'+approvalAge+' س</b><small>زمن الموافقات التقديري</small></div></div>');};

  function workforceView(){open('<div class="workspace-head"><div><h2>القوى العاملة AI</h2><p class="muted">'+state.employees.length+' سجلات مرتبطة بمصدر واحد</p></div><div class="detail-actions"><button class="primary" id="add-from-workforce">إضافة موظف</button>'+closeButton()+'</div></div><div class="workspace-list">'+state.employees.map(e=>'<button class="workspace-row" data-open-emp="'+e.id+'"><span class="mini-unit"><span class="ai-unit"><i class="antenna"></i><i class="head"><i class="face"><i></i><i></i></i></i><i class="body"></i></span></span><span><b>'+esc(e.name)+'</b><small>'+esc(e.role)+' · '+esc(e.department)+'</small></span><span><b>'+e.progress+'%</b><small>'+esc(status(e.status))+'</small></span></button>').join('')+'</div>');$("#add-from-workforce").onclick=addEmployeeView;document.querySelectorAll('[data-open-emp]').forEach(x=>x.onclick=()=>employee(x.dataset.openEmp));}
  function projectsView(){open('<div class="workspace-head"><div><h2>المشاريع النشطة</h2><p class="muted">مشروعات تشترك في نفس الموظفين والمهام والتقارير</p></div>'+closeButton()+'</div><div class="project-cards">'+state.projects.map(p=>'<button class="project-workspace-card" data-open-project="'+p.id+'"><span><b>'+esc(p.name)+'</b><small>'+esc(p.phase)+'</small></span><strong>'+p.progress+'%</strong><div class="bar"><i style="width:'+p.progress+'%"></i></div><small>'+state.tasks.filter(t=>t.project===p.id).length+' مهام · '+state.reports.filter(r=>r.project===p.id).length+' تقارير</small></button>').join('')+'</div>');document.querySelectorAll('[data-open-project]').forEach(x=>x.onclick=()=>project(x.dataset.openProject));}
  function tasksView(){open('<div class="workspace-head"><div><h2>مركز المهام</h2><p class="muted">كل مهمة متصلة بموظف ومشروع وسجل أحداث</p></div>'+closeButton()+'</div><div class="workspace-list">'+state.tasks.map(t=>{const e=emp(t.employee),p=pr(t.project);return '<button class="workspace-row" data-task="'+t.id+'"><span><b>'+esc(t.title)+'</b><small>'+esc(p.name)+' · '+esc(e.name)+'</small></span><span><b>'+t.progress+'%</b><small>'+esc(t.status)+'</small></span></button>'}).join('')+'</div>');document.querySelectorAll('[data-task]').forEach(x=>x.onclick=()=>taskView(x.dataset.task));}
  function reportsView(){open('<div class="workspace-head"><div><h2>التقارير والمخرجات</h2><p class="muted">سجل دائم لا يحذف التقارير المكتملة</p></div>'+closeButton()+'</div><div class="workspace-list">'+state.reports.map(r=>'<button class="workspace-row" data-open-report="'+r.id+'"><span><b>'+esc(r.title)+'</b><small>'+esc(emp(r.author).name)+' · '+esc(pr(r.project).name)+'</small></span><span><b>'+r.progress+'%</b><small>'+esc(r.stage)+'</small></span></button>').join('')+'</div>');document.querySelectorAll('[data-open-report]').forEach(x=>x.onclick=()=>report(x.dataset.openReport));}
  function decisionsView(){open('<div class="workspace-head"><div><h2>مركز قرارات نواف</h2><p class="muted">لا يُنفذ النشر أو الإنفاق أو التغييرات الحساسة دون اعتماد</p></div>'+closeButton()+'</div>'+(state.decisions.length?state.decisions.map(d=>'<div class="decision-detail"><div><h3>'+esc(d.title)+'</h3><p><b>السبب:</b> '+esc(d.reason)+'</p><p><b>الفائدة المتوقعة:</b> '+esc(d.expectedBenefit)+'</p><div class="workspace-badges"><span class="badge">'+esc(d.requester)+'</span><span class="badge">'+esc(d.project)+'</span><span class="badge">'+esc(d.department)+'</span><span class="badge wait">تكلفة '+esc(d.cost)+'</span><span class="badge">مخاطر '+esc(d.risk)+'</span><span class="badge">'+esc(d.time)+'</span></div></div><div class="buttons"><button class="ok" data-action="approve" data-id="'+d.id+'">اعتماد وتنفيذ</button><button data-action="changes" data-id="'+d.id+'">طلب تعديلات</button><button data-action="reject" data-id="'+d.id+'">رفض</button></div></div>').join(''):'<div class="empty-state">لا توجد قرارات معلقة</div>'));document.querySelectorAll('[data-action]').forEach(x=>x.onclick=()=>approve(x.dataset.action,x.dataset.id));}
  function managerView(){const active=state.tasks.filter(t=>t.progress<100),blocked=state.employees.filter(e=>e.status==='WAITING_APPROVAL'),overloaded=state.employees.filter(e=>state.tasks.filter(t=>t.employee===e.id&&t.progress<100).length>1),latest=state.activities.slice(0,4);open('<div class="workspace-head"><div><h2>المدير العام AI</h2><p class="muted">ملخص تنفيذي مشتق من حالة الشركة الآن</p></div><span class="badge real">🔵 تحليل داخلي</span>'+closeButton()+'</div><div class="executive-summary"><div class="health-ring" style="--health:'+Math.round(state.projects.reduce((n,p)=>n+p.progress,0)/state.projects.length)+'"><b>'+Math.round(state.projects.reduce((n,p)=>n+p.progress,0)/state.projects.length)+'%</b><small>صحة الشركة</small></div><div><h3>ما يحدث الآن</h3><p>'+active.length+' مهام نشطة، '+state.reports.filter(r=>r.progress<100).length+' تقارير تتقدم، و '+state.requests.length+' طلبات تعاون بين الأقسام.</p><h3>ما يحتاج نواف</h3><p>'+(state.decisions.length?state.decisions.map(d=>esc(d.title)).join('، '):'لا يوجد تصعيد مهم حاليًا')+'</p></div></div><div class="detail-grid"><div class="detail-box"><b>'+blocked.length+'</b><small>موظفون متوقفون</small></div><div class="detail-box"><b>'+overloaded.length+'</b><small>ضغط عمل مرتفع</small></div><div class="detail-box"><b>'+state.reports.filter(r=>r.progress===100).length+'</b><small>مخرجات مكتملة</small></div></div><h3>آخر التغييرات المهمة</h3><div class="timeline">'+latest.map(a=>'<div class="timeline-item"><time>'+clock(a.createdAt)+'</time><i></i><span>'+esc(a.text)+'</span></div>').join('')+'</div>');}

  window.approve=function(action,id){const d=state.decisions.find(x=>x.id===id);if(!d)return;if(action==='approve'){state.decisions=state.decisions.filter(x=>x.id!==id);let t=state.tasks.find(x=>x.id==='t1');t.progress=Math.max(t.progress,55);t.status='ACTIVE';t.history.unshift({at:now(),text:'اعتمد نواف التنفيذ وبدأت مرحلة إعداد الموجز'});const omar=emp('omar');omar.status='WORKING';omar.task='موجز الحملة للتصميم';let design=state.tasks.find(x=>x.title==='تصاميم حملة قدّها');if(!design){design={id:'design-'+Date.now(),title:'تصاميم حملة قدّها',employee:'lian',project:'q',progress:8,status:'ACTIVE',history:[{at:now(),text:'استلمت ليان طلب التصميم من قسم التسويق'}]};state.tasks.push(design);}const lian=emp('lian');lian.status='COLLABORATING';lian.task=design.title;state.requests.push({id:'req-'+Date.now(),title:'تصميم حملة قدّها',from:'التسويق',to:'التصميم',status:'قيد التنفيذ',task:design.id,createdAt:now()});event('نواف اعتمد: '+d.title,'REAL',{employee:'omar',project:'q',task:'t1'});event('تم إرسال النتائج إلى قسم التصميم','SIM',{employee:'lian',project:'q',task:design.id});toast('تم الاعتماد وبدأ مسار التنفيذ');}else if(action==='changes'){d.status='CHANGES_REQUESTED';event('نواف طلب تعديلات على '+d.title,'APPROVAL',{project:'q'});toast('أعيد القرار لصاحب الطلب');}else{state.decisions=state.decisions.filter(x=>x.id!==id);event('نواف رفض: '+d.title,'REAL',{project:'q'});toast('تم إيقاف التدفق بأمان');}save();render();};
  window.advance=function(){const t=state.tasks.find(t=>t.progress<100&&emp(t.employee)&&emp(t.employee).status!=="WAITING_APPROVAL");if(!t)return toast('لا توجد مهمة قابلة للتقدم');t.progress=Math.min(100,t.progress+18);t.status=t.progress===100?'COMPLETED':'ACTIVE';t.history=t.history||[];t.history.unshift({at:now(),text:'تقدمت المهمة إلى '+t.progress+'%'});const e=emp(t.employee);e.progress=t.progress;e.status=t.progress===100?'COMPLETED':(e.id==='noura'?'REPORTING':'WORKING');event(e.name+' حدّث '+t.title+' إلى '+t.progress+'%','SIM',{employee:e.id,project:t.project,task:t.id});let r=state.reports.find(r=>r.task===t.id||r.author===e.id&&r.project===t.project);if(!r&&t.progress>=60){r={id:'r-'+Date.now(),title:'مخرجات '+t.title,author:e.id,department:e.department,project:t.project,task:t.id,status:stage(t.progress),stage:stage(t.progress),progress:t.progress,content:'نتائج داخلية محفوظة ناتجة عن سير المهمة، جاهزة للتوسعة والمراجعة.',createdAt:now(),updatedAt:now(),completedAt:null,history:[]};state.reports.push(r);event(e.name+' أنشأ مخرجًا محفوظًا','SIM',{employee:e.id,project:t.project,task:t.id,report:r.id});}if(r){r.task=r.task||t.id;r.progress=t.progress;r.stage=stage(t.progress);r.status=r.stage;r.updatedAt=now();r.completedAt=t.progress===100?r.updatedAt:null;r.history=r.history||[];r.history.unshift({at:r.updatedAt,stage:r.stage,progress:r.progress});}if(t.progress===100){e.completedTaskIds=e.completedTaskIds||[];if(!e.completedTaskIds.includes(t.id))e.completedTaskIds.push(t.id);event(e.name+' أكمل المهمة وأصبح التقرير متاحًا','SIM',{employee:e.id,project:t.project,task:t.id,report:r&&r.id});}const p=pr(t.project);p.progress=Math.round(state.tasks.filter(x=>x.project===p.id).reduce((n,x)=>n+x.progress,0)/state.tasks.filter(x=>x.project===p.id).length);p.health=p.progress;save();render();toast('تقدم '+t.title+': '+t.progress+'%');};

  const oldBind=window.bind;window.bind=function(){oldBind();const q=document.querySelector('.search');if(q){q.addEventListener('input',()=>{document.querySelector('.search-results')?.remove();const v=q.value.trim();if(!v)return;const people=state.employees.filter(e=>(e.name+e.role+e.department).includes(v)).slice(0,4),projects=state.projects.filter(p=>p.name.includes(v)),tasks=state.tasks.filter(t=>t.title.includes(v)).slice(0,4);const box=document.createElement('div');box.className='search-results';box.innerHTML=(people.map(e=>'<button data-search-emp="'+e.id+'"><span>'+esc(e.name)+'</span><small>'+esc(e.role)+'</small></button>').join('')+projects.map(p=>'<button data-search-project="'+p.id+'"><span>'+esc(p.name)+'</span><small>مشروع</small></button>').join('')+tasks.map(t=>'<button data-search-task="'+t.id+'"><span>'+esc(t.title)+'</span><small>مهمة</small></button>').join(''))||'<div class="empty-state">لا توجد نتائج</div>';document.querySelector('.topbar').appendChild(box);box.querySelectorAll('[data-search-emp]').forEach(x=>x.onclick=()=>employee(x.dataset.searchEmp));box.querySelectorAll('[data-search-project]').forEach(x=>x.onclick=()=>project(x.dataset.searchProject));box.querySelectorAll('[data-search-task]').forEach(x=>x.onclick=()=>taskView(x.dataset.searchTask));});}$("#workforce").onclick=workforceView;$("#projects-nav").onclick=projectsView;$("#reports-nav").onclick=reportsView;$("#manager-card").onclick=managerView;$("#manager-core").onclick=managerView;document.querySelectorAll('[data-dashboard]').forEach(x=>x.onclick=()=>({workforce:workforceView,tasks:tasksView,reports:reportsView,decisions:decisionsView,analytics:analytics}[x.dataset.dashboard]||analytics)());}
  render();
  document.addEventListener('click',e=>{const t=e.target.closest('[data-task]');if(t)taskView(t.dataset.task);const decision=e.target.closest('.approval');if(decision&&!e.target.closest('button')){const title=decision.querySelector('strong').innerText.replace('🟠','').trim(),d=state.decisions.find(x=>x.title===title);if(d)open('<div class="workspace-head"><div><h2>'+esc(d.title)+'</h2><p class="muted">🟠 بانتظار موافقة نواف</p></div>'+closeButton()+'</div><div class="detail-grid"><div class="detail-box"><b>'+esc(d.requester)+'</b><small>مقدم الطلب</small></div><div class="detail-box"><b>'+esc(d.project)+'</b><small>المشروع</small></div><div class="detail-box"><b>'+esc(d.department)+'</b><small>القسم</small></div><div class="detail-box"><b>'+esc(d.risk)+'</b><small>المخاطر</small></div><div class="detail-box"><b>'+esc(d.cost)+'</b><small>التكلفة</small></div><div class="detail-box"><b>'+esc(d.time)+'</b><small>الوقت المتوقع</small></div></div><h3>سبب القرار</h3><p>'+esc(d.reason)+'</p>');}const feed=e.target.closest('.feed > div');if(feed){const text=feed.querySelector('span')?.innerText,a=state.activities.find(x=>x.text===text);if(a&&a.links){if(a.links.report)return report(a.links.report);if(a.links.task)return taskView(a.links.task);if(a.links.employee)return employee(a.links.employee);if(a.links.project)return project(a.links.project);}}});
})();
